-- Trace: facility -> clinician -> encounter -> assessment -> symptoms/social
SELECT COUNT(*) FROM facilities f 
JOIN clinicians c ON f.fackey = c.facconnect;

-- Check: encounter -> assessment -> symptoms
SELECT COUNT(*) FROM encounters e 
JOIN assessmentbasics ab ON e.abref = ab.abkey;

